CREATE TABLE [sales].[SalesInvoices]([InvoiceId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SalesInvoices_Id] DEFAULT NEWSEQUENTIALID(),[InvoiceNumber] NVARCHAR(50) NOT NULL,[InvoiceDate] DATETIMEOFFSET NOT NULL,[CounterId] UNIQUEIDENTIFIER NULL,[ShiftId] UNIQUEIDENTIFIER NULL,[CustomerId] UNIQUEIDENTIFIER NULL,[WarehouseId] UNIQUEIDENTIFIER NOT NULL,[TenantId] UNIQUEIDENTIFIER NULL,[SalesPersonId] UNIQUEIDENTIFIER NULL,[Subtotal] DECIMAL(18,2) NOT NULL,[DiscountAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_Discount] DEFAULT 0,[TaxAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_Tax] DEFAULT 0,[RoundOff] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_Round] DEFAULT 0,[DeliveryCharge] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_DeliveryCharge] DEFAULT 0,[DeliveryTaxAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_DeliveryTaxAmount] DEFAULT 0,[PromotionDiscountAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_PromotionDiscountAmount] DEFAULT 0,[AppliedPromotionId] UNIQUEIDENTIFIER NULL,[AppliedPromotionName] NVARCHAR(150) NULL,[FreeDeliveryApplied] BIT NOT NULL CONSTRAINT [DF_SalesInvoices_FreeDeliveryApplied] DEFAULT 0,[FreeDeliveryThresholdSnapshot] DECIMAL(18,2) NULL,[ServicePincode] VARCHAR(6) NULL,[GrandTotal] DECIMAL(18,2) NOT NULL,[PaidAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoices_Paid] DEFAULT 0,[BalanceAmount] AS([GrandTotal]-[PaidAmount]) PERSISTED,[Status] NVARCHAR(20) NOT NULL,[Remarks] NVARCHAR(1000) NULL,[OriginalInvoiceId] UNIQUEIDENTIFIER NULL,[CreatedBy] NVARCHAR(256) NULL,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_SalesInvoices_Created] DEFAULT SYSUTCDATETIME(),[ModifiedOn] DATETIMEOFFSET NULL,[RowVersion] ROWVERSION NOT NULL,CONSTRAINT [PK_SalesInvoices] PRIMARY KEY([InvoiceId]),CONSTRAINT [UQ_SalesInvoices_Number] UNIQUE([InvoiceNumber]),CONSTRAINT [FK_SalesInvoices_Counter] FOREIGN KEY([CounterId]) REFERENCES [sales].[POSCounters]([CounterId]),CONSTRAINT [FK_SalesInvoices_Shift] FOREIGN KEY([ShiftId]) REFERENCES [sales].[POSShift]([ShiftId]),CONSTRAINT [FK_SalesInvoices_Customer] FOREIGN KEY([CustomerId]) REFERENCES [sales].[Customers]([CustomerId]),CONSTRAINT [FK_SalesInvoices_Warehouse] FOREIGN KEY([WarehouseId]) REFERENCES [inventory].[Warehouses]([WarehouseId]),CONSTRAINT [FK_SalesInvoices_Tenants] FOREIGN KEY([TenantId]) REFERENCES [core].[Tenants]([TenantId]),CONSTRAINT [FK_SalesInvoices_Original] FOREIGN KEY([OriginalInvoiceId]) REFERENCES [sales].[SalesInvoices]([InvoiceId]),CONSTRAINT [CK_SalesInvoices_StorefrontAmounts] CHECK([DeliveryCharge]>=0 AND [DeliveryTaxAmount]=0 AND [PromotionDiscountAmount]>=0 AND ([FreeDeliveryThresholdSnapshot] IS NULL OR [FreeDeliveryThresholdSnapshot]>0)),CONSTRAINT [CK_SalesInvoices_Status] CHECK([Status]='PARTIALLY_RETURNED' OR [Status]='RETURNED' OR [Status]='VOID' OR [Status]='CANCELLED' OR [Status]='COMPLETED' OR [Status]='SUSPENDED' OR [Status]='HELD' OR [Status]='DRAFT'));
GO
CREATE INDEX [IX_SalesInvoices_TenantId_Date] ON [sales].[SalesInvoices]([TenantId],[InvoiceDate]);
GO
CREATE INDEX [IX_SalesInvoices_Date] ON [sales].[SalesInvoices]([InvoiceDate] DESC,[Status],[WarehouseId]);
